CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE "Category" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(100) NOT NULL UNIQUE
);

INSERT INTO "Category" ("name") VALUES
    ('alumbrado'),
    ('limpieza'),
    ('mobiliario urbano'),
    ('tráfico y semáforos'),
    ('arbolado'),
    ('otros');

CREATE TABLE "Incident" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "title" varchar(255) NOT NULL,
    "description" varchar,
    "category_id" integer,
    "location" geometry(Point, 4326) NOT NULL,
    "status_id" integer NOT NULL DEFAULT 1,
    "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "fk_incident_category"
        FOREIGN KEY ("category_id") REFERENCES "Category" ("id")
);

COMMENT ON COLUMN "Incident"."status_id" IS
    'Status lookup id; 1 represents REPORTED until the Status table is included.';

CREATE INDEX "idx_incident_location_gist"
    ON "Incident" USING GIST ("location");

CREATE INDEX "idx_incident_category_id"
    ON "Incident" ("category_id");
